import re

_SKU_RE = re.compile(r"^([A-Z]{2,4})/(\d{4})/([A-Za-z])$")


def bulk_discount(qty):
    if qty >= 100:
        return 0.15
    if qty >= 20:
        return 0.05
    return 0.0


def line_total(unit_price, qty):
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


def parse_sku(s):
    if not isinstance(s, str):
        raise ValueError("SKU must be a string")
    m = _SKU_RE.match(s)
    if not m or not m.group(3).isupper():
        raise ValueError("invalid SKU: " + repr(s))
    return {"category": m.group(1), "number": int(m.group(2)), "variant": m.group(3)}

BASE_COST = {1: 5.0, 2: 12.0, 3: 25.0}


def shipping_zone(country_code):
    """Return the shipping zone for a country code.

    1 for JP, 2 for KR or SG, 3 for any other code.
    """
    if country_code == "JP":
        return 1
    if country_code in ("KR", "SG"):
        return 2
    return 3


def shipping_cost(weight_kg, zone):
    """Return base + 0.8 * weight_kg for the zone, rounded to 2 decimals."""
    base = BASE_COST[zone]
    return round(base + 0.8 * weight_kg, 2)


def is_oversize(l, w, h):
    """Return True if any dimension exceeds 150 or l + w + h exceeds 360."""
    return l > 150 or w > 150 or h > 150 or (l + w + h) > 360

